import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  
  // 🟢 අලුතින් 'username' කියන Field එක එකතු කළා
  const [formData, setFormData] = useState({ 
    name: '', 
    username: '', 
    grade: 'Grade 10', 
    subjects: '', 
    phone_number: '', 
    address: '', 
    password: 'ST@123' 
  });
  
  const [searchQuery, setSearchQuery] = useState('');

  // 🟢 දත්ත ලබා ගැනීම (Read)
  const fetchStudents = () => {
    axios.get('http://localhost:8081/api/view-students')
      .then(res => setStudents(res.data))
      .catch(err => console.error("Error fetching students:", err));
  };

  useEffect(() => { fetchStudents(); }, []);

  // 🟢 ඇතුළත් කිරීම හෝ Update කිරීම (Create / Update)
  const handleSubmit = (e) => {
    e.preventDefault();
    
    if(!formData.subjects) {
      alert("Please select at least one subject!");
      return;
    }

    if (isEditing) {
      // 🟢 Update කිරීම (Backend එකේ PUT route එකක් ඕනේ)
      axios.put(`http://localhost:8081/api/update-student/${editId}`, formData)
        .then(res => {
          fetchStudents();
          resetForm();
          alert("✅ Student Updated Successfully!");
        })
        .catch(err => {
          console.error(err);
          alert("Error updating. Ensure backend PUT route exists.");
        });
    } else {
      // 🟢 අලුතින් ඇතුළත් කිරීම (Save)
      axios.post('http://localhost:8081/api/add-student', formData)
        .then(res => {
          if(res.data.status === "Success") {
            fetchStudents();
            resetForm();
            alert("✅ Student Registered Successfully!");
          }
        })
        .catch(err => console.error("Error saving data:", err));
    }
  };

  // 🟢 Delete කිරීම (Backend එකේ DELETE route එකක් ඕනේ)
  const handleDelete = (id) => {
    if(window.confirm("Are you sure you want to remove this student?")) {
      axios.delete(`http://localhost:8081/api/delete-student/${id}`)
        .then(res => {
          fetchStudents();
          alert("🗑️ Student Removed!");
        })
        .catch(err => {
            console.error(err);
            alert("Error deleting. Ensure backend DELETE route exists.");
            // UI එකෙන් විතරක් අයින් කරලා පෙන්වන්න
            setStudents(students.filter(s => s.id !== id)); 
        });
    }
  };

  // 🟢 Edit Button එක Click කළාම
  const handleEdit = (student) => {
    setIsEditing(true);
    setEditId(student.id);
    setFormData({
      name: student.name,
      username: student.username || '', // පරණ දත්ත වල නැත්නම් හිස්ව තියන්න
      grade: student.grade,
      subjects: student.subjects,
      phone_number: student.phone_number,
      address: student.address,
      password: student.password || 'ST@123'
    });
    setShowForm(true);
  };

  // 🟢 Form එක හිස් කිරීම
  const resetForm = () => {
    setShowForm(false);
    setIsEditing(false);
    setEditId(null);
    setFormData({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', address: '', password: 'ST@123' });
  };

  // Checkbox Control
  const handleSubjectChange = (subject, isChecked) => {
    let currentSubjects = formData.subjects ? formData.subjects.split(', ') : [];
    if (isChecked) {
      currentSubjects.push(subject);
    } else {
      currentSubjects = currentSubjects.filter(s => s !== subject);
    }
    setFormData({ ...formData, subjects: currentSubjects.join(', ') });
  };

  const filteredStudents = [...students]
    .reverse()
    .filter(s => 
      s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.grade.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.phone_number.includes(searchQuery)
    );

  const availableSubjects = ['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies', 'Dancing', 'History'];

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      
      {/* 🟢 Header & Search */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)', flexWrap: 'wrap', gap: '15px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '22px' }}>🧑‍🎓 Manage Students</h2>
        
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <input 
            type="text" 
            placeholder="Search by Name, Grade or Phone..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', width: '280px', fontSize: '13px' }}
          />
          
          <button 
            onClick={() => { resetForm(); setShowForm(true); }} 
            style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', boxShadow: '0 4px 10px rgba(21,128,61,0.2)' }}>
            + Register Student
          </button>
        </div>
      </div>

      {/* 🟢 Students Table */}
      <div style={{ backgroundColor: '#fff', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>No.</th>
              <th style={thStyle}>Student Info</th>
              <th style={thStyle}>Grade</th>
              <th style={thStyle}>Enrolled Subjects</th>
              <th style={thStyle}>Contact Details</th>
              <th style={{...thStyle, textAlign: 'center'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredStudents.length > 0 ? filteredStudents.map((s, index) => (
              <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9', transition: '0.2s' }}>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#1e293b'}}>{index + 1}</td>
                <td style={tdStyle}>
                    <div style={{ fontWeight: 'bold', color: '#15803d' }}>{s.name}</div>
                    <div style={{ fontSize: '12px', color: '#64748b' }}>Username: {s.username || 'Not Set'}</div>
                </td>
                <td style={tdStyle}>
                  <span style={{ backgroundColor: '#f1f5f9', padding: '4px 8px', borderRadius: '4px', fontSize: '12px', fontWeight: 'bold', color: '#475569' }}>{s.grade}</span>
                </td>
                <td style={{...tdStyle, color: '#1e293b', fontSize: '13px'}}>{s.subjects}</td>
                <td style={tdStyle}>
                  <div style={{ fontWeight: 'bold', color: '#475569', fontSize: '13px' }}>📞 {s.phone_number}</div>
                  <div style={{ fontSize: '12px', color: '#94a3b8' }}>{s.address ? s.address : '-'}</div>
                </td>
                <td style={{...tdStyle, textAlign: 'center'}}>
                  <button onClick={() => handleEdit(s)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' }}>✏️</button>
                  <button onClick={() => handleDelete(s.id)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan="6" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>
                  No students found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* 🟢 Add / Edit Modal Form */}
      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '500px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)', maxHeight: '90vh', overflowY: 'auto' }}>
            
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b', fontSize: '20px', borderBottom: '1px solid #f1f5f9', paddingBottom: '10px' }}>
                {isEditing ? '✏️ Edit Student Details' : '➕ Register New Student'}
            </h3>
            
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              
              <div style={{ display: 'flex', gap: '15px' }}>
                  <input type="text" placeholder="Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={{...inputStyle, flex: 1}} />
                  {/* 🟢 Username Field එක (Login වෙන්න) */}
                  <input type="text" placeholder="Username (For Login)" value={formData.username} onChange={(e) => setFormData({...formData, username: e.target.value})} required style={{...inputStyle, flex: 1}} />
              </div>
              
              <select value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} style={inputStyle}>
                {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026', 'A/L 2027'].map(g => <option key={g} value={g}>{g}</option>)}
              </select>

              {/* Multiple Subjects Select */}
              <div style={{ padding: '15px', border: '1px solid #cbd5e1', borderRadius: '8px', backgroundColor: '#f8fafc' }}>
                <p style={{ margin: '0 0 10px 0', fontSize: '13px', fontWeight: 'bold', color: '#475569' }}>Select Subjects:</p>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                  {availableSubjects.map(sub => (
                    <label key={sub} style={{ fontSize: '13px', color: '#1e293b', display: 'flex', alignItems: 'center', gap: '5px', cursor: 'pointer' }}>
                      <input 
                        type="checkbox" 
                        checked={formData.subjects.includes(sub)}
                        onChange={(e) => handleSubjectChange(sub, e.target.checked)}
                      /> {sub}
                    </label>
                  ))}
                </div>
              </div>

              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              
              <input type="text" placeholder="Address (Optional)" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
              
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={{ padding: '10px 20px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px 25px', backgroundColor: isEditing ? '#3b82f6' : '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' }}>
                    {isEditing ? 'Update Student' : 'Register Student'}
                </button>
              </div>
            </form>

          </div>
        </div>
      )}
    </div>
  );
}

// Styles
const inputStyle = { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '14px', outline: 'none', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', color: '#475569', fontSize: '14px', textAlign: 'left' };
const tdStyle = { padding: '15px', fontSize: '14px' };
